CREATE TABLE login_event (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TIMESTAMP NOT NULL,
    updated_at TIMESTAMP NOT NULL,
    user_id BIGINT,
    ip VARCHAR(255) NOT NULL,
    user_agent VARCHAR(1000) NOT NULL,
    success BOOLEAN NOT NULL
);

CREATE INDEX idx_login_event_user ON login_event (user_id);
CREATE INDEX idx_login_event_ip ON login_event (ip);
CREATE INDEX idx_login_event_success ON login_event (success);
CREATE INDEX idx_login_event_created ON login_event (created_at);
